// Tiled GEMM + bias kernel
// A: [M, K] row-major, B (weight): [N, K] row-major (we compute A * B^T)
// C: [M, N] row-major, bias: [N]
// Tile: BM=128, BN=128, BK=32
#define GEMM_BM 128
#define GEMM_BN 128
#define GEMM_BK 32

__launch_bounds__(256, 1)
__global__ void sgemm_bias_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ bias,
    float* __restrict__ C,
    int M, int N, int K)
{
    // Each block computes a GEMM_BM x GEMM_BN tile of C
    // blockDim = (16, 16) -> 256 threads
    // Each thread computes an 8x8 subtile
    const int THREAD_M = 8;
    const int THREAD_N = 8;
    const int BLOCK_DIM_X = GEMM_BN / THREAD_N; // 16
    const int BLOCK_DIM_Y = GEMM_BM / THREAD_M; // 16

    int bx = blockIdx.x; // tile col index
    int by = blockIdx.y; // tile row index

    int tx = threadIdx.x % BLOCK_DIM_X;
    int ty = threadIdx.x / BLOCK_DIM_X;

    int row_start = by * GEMM_BM;
    int col_start = bx * GEMM_BN;

    __shared__ float As[2][GEMM_BK][GEMM_BM];
    __shared__ float Bs[2][GEMM_BK][GEMM_BN];

    float acc[THREAD_M][THREAD_N];
    #pragma unroll
    for (int i = 0; i < THREAD_M; i++)
        #pragma unroll
        for (int j = 0; j < THREAD_N; j++)
            acc[i][j] = 0.0f;

    int tid = threadIdx.x; // 0..255
    int num_k_tiles = (K + GEMM_BK - 1) / GEMM_BK;

    // Preload first tile
    {
        // Load A tile: GEMM_BM x GEMM_BK = 128x32 = 4096 elements, 256 threads -> 16 per thread
        int a_load_count = (GEMM_BM * GEMM_BK) / 256; // 16
        #pragma unroll
        for (int i = 0; i < a_load_count; i++) {
            int idx = tid + i * 256;
            int r = idx % GEMM_BM;
            int k = idx / GEMM_BM;
            int global_r = row_start + r;
            int global_k = 0 * GEMM_BK + k;
            float val = (global_r < M && global_k < K) ? A[global_r * K + global_k] : 0.0f;
            As[0][k][r] = val;
        }
        // Load B tile: GEMM_BN x GEMM_BK = 128x32 = 4096 elements, 256 threads -> 16 per thread
        int b_load_count = (GEMM_BN * GEMM_BK) / 256; // 16
        #pragma unroll
        for (int i = 0; i < b_load_count; i++) {
            int idx = tid + i * 256;
            int c = idx % GEMM_BN;
            int k = idx / GEMM_BN;
            int global_c = col_start + c;
            int global_k = 0 * GEMM_BK + k;
            float val = (global_c < N && global_k < K) ? B[global_c * K + global_k] : 0.0f;
            Bs[0][k][c] = val;
        }
    }
    __syncthreads();

    for (int tile = 0; tile < num_k_tiles; tile++) {
        int cur = tile & 1;
        int nxt = 1 - cur;

        // Prefetch next tile
        if (tile + 1 < num_k_tiles) {
            int a_load_count = (GEMM_BM * GEMM_BK) / 256;
            #pragma unroll
            for (int i = 0; i < a_load_count; i++) {
                int idx = tid + i * 256;
                int r = idx % GEMM_BM;
                int k = idx / GEMM_BM;
                int global_r = row_start + r;
                int global_k = (tile + 1) * GEMM_BK + k;
                float val = (global_r < M && global_k < K) ? A[global_r * K + global_k] : 0.0f;
                As[nxt][k][r] = val;
            }
            int b_load_count = (GEMM_BN * GEMM_BK) / 256;
            #pragma unroll
            for (int i = 0; i < b_load_count; i++) {
                int idx = tid + i * 256;
                int c = idx % GEMM_BN;
                int k = idx / GEMM_BN;
                int global_c = col_start + c;
                int global_k = (tile + 1) * GEMM_BK + k;
                float val = (global_c < N && global_k < K) ? B[global_c * K + global_k] : 0.0f;
                Bs[nxt][k][c] = val;
            }
        }

        // Compute
        #pragma unroll
        for (int k = 0; k < GEMM_BK; k++) {
            float a_frag[THREAD_M];
            float b_frag[THREAD_N];
            #pragma unroll
            for (int i = 0; i < THREAD_M; i++)
                a_frag[i] = As[cur][k][ty * THREAD_M + i];
            #pragma unroll
            for (int j = 0; j < THREAD_N; j++)
                b_frag[j] = Bs[cur][k][tx * THREAD_N + j];
            #pragma unroll
            for (int i = 0; i < THREAD_M; i++)
                #pragma unroll
                for (int j = 0; j < THREAD_N; j++)
                    acc[i][j] += a_frag[i] * b_frag[j];
        }

        if (tile + 1 < num_k_tiles)
            __syncthreads();
    }

    // Write output with bias
    #pragma unroll
    for (int i = 0; i < THREAD_M; i++) {
        int global_r = row_start + ty * THREAD_M + i;
        if (global_r >= M) continue;
        #pragma unroll
        for (int j = 0; j < THREAD_N; j++) {
            int global_c = col_start + tx * THREAD_N + j;
            if (global_c >= N) continue;
