    __shared__ float Bs[TILE_K][TILE_N + 1];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;

    int row_base = by * TILE_M;
    int col_base = bx * TILE_N;

    int num_tiles = (K + TILE_K - 1) / TILE_K;

    float acc[8][4] = {0.0f};

    int thread_row = tx / 16;
    int thread_col = (tx % 16) * 4;

    for (int t = 0; t < num_tiles; t++) {
        int k_base = t * TILE_K;

        for (int load_idx = tx; load_idx < TILE_M * TILE_K; load_idx += THREADS_PER_BLOCK) {
            int load_row = load_idx / TILE_K;
            int load_col = load_idx % TILE_K;
