        for (int load_idx = tx; load_idx < TILE_K * TILE_N; load_idx += THREADS_PER_BLOCK) {
            int load_row = load_idx / TILE_N;
            int load_col = load_idx % TILE_N;
            int global_row = k_base + load_row;
            int global_col = col_base + load_col;
            Bs[load_row][load_col] = (global_row < K && global_col < N) ? B[global_row * N + global_col] : 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_K; k++) {
            #pragma unroll
            for (int i = 0; i < 8; i++) {
                int a_row = thread_row + i * 16;
                float a_val = (a_row < TILE_M) ? As[a_row][k] : 0.0f;
                #pragma unroll
